const body = $json.body ?? $json;
const senderId = String(body.sender_id ?? '').trim();
const artifactId = String(body.artifact_id ?? '').trim();
const requestedTtl = Number(body.ttl_seconds ?? 900);
const ttlSeconds = Number.isFinite(requestedTtl)
  ? Math.min(Math.max(Math.trunc(requestedTtl), 60), 3600)
  : 900;

if (!senderId || !artifactId) {
  return {
    json: {
      request_valid: false,
      status_code: 400,
      reply: 'Informe sender_id e artifact_id para criar o token temporário.',
    },
  };
}

return {
  json: {
    request_valid: true,
    sender_id: senderId,
    artifact_id: artifactId,
    ttl_seconds: ttlSeconds,
  },
};

const input = $input.item.json;

if (!input.grant_created) {
  return {
    json: {
      status_code: 404,
      grant_created: false,
      sender_id: input.sender_id,
      artifact_id: input.artifact_id,
      reply: 'PDF não encontrado para este remetente.',
    },
  };
}

return {
  json: {
    status_code: 201,
    grant_created: true,
    grant_id: input.persisted_grant_id,
    sender_id: input.sender_id,
    artifact_id: input.artifact_id,
    download_header: 'X-Download-Grant',
    download_token: input.raw_token,
    expires_at: input.persisted_expires_at,
    reply: 'Token temporário criado para este PDF.',
  },
};
